297: export function playerStats(state) {
298:   const g = state.combat?.gear || state.gear || { weapon: 1, armor: 1, stim: 0 };
299:   const lvl = Math.max(1, state.level || 1);
300:   const outfits = state.outfits || {};
301:   const duster = Math.max(0, Math.floor(outfits.duster || 0));
302:   const rebreather = Math.max(0, Math.floor(outfits.rebreather || 0));
303:   const charm = Math.max(0, Math.floor(outfits.charm || 0));
304:   const str = attrLevel(state, 'str');
305:   const vit = attrLevel(state, 'vit');
306:   const agi = attrLevel(state, 'agi');
307:   const luk = attrLevel(state, 'luk');
308:   const baseHp = 100 + 30 * (g.armor - 1) + vit * 8;
309:   const maxHp = Math.max(1, Math.round(
310:     baseHp
311:     * levelHpMult(state)
312:     * (1 + duster * 0.025)
313:     * perkHpMult(state)
314:   ));
315:   const attack = (4 + 4 * (g.weapon - 1))
316:     * levelAtkMult(state)
317:     * (1 + str * 0.025)
318:     * shardDamageMult(state)
319:     * perkAtkMult(state);
320:   const crit = Math.min(0.60, 0.12 + rebreather * 0.015 + agi * 0.006 + perkCritBonus(state));
321:   const defense = Math.min(0.68, 0.035 * (g.armor - 1) + duster * 0.006 + vit * 0.004);
322:   const capsMult = (1 + charm * 0.03) * (1 + luk * 0.015) * perkCapsMult(state);
323:   return {
324:     maxHp,
325:     attack,
326:     crit,
327:     defense,
328:     capsMult,
329:     oreMult: oreMultiplier(state),
330:     xpMult: xpMultiplier(state),
331:     healPerKill: (g.stim > 0 ? 8 + 5 * g.stim : 6) + perkHealBonus(state),
332:     deathMs: Math.max(1500, 4000 - 250 * g.stim),
333:     speedMult: perkSpeedMult(state),
334:     level: lvl,
335:   };
336: }
