371: /* ── formatting helpers ────────────────────────────────────── */
372: export function fmt(n, digits = 0) {
373:   if (!isFinite(n)) return '∞';
374:   const abs = Math.abs(n);
375:   if (abs < 1000) {
376:     if (abs === 0) return '0';
377:     if (abs < 10 && digits > 0) return n.toFixed(digits);
378:     if (abs < 100 && digits > 0 && n % 1 !== 0) return n.toFixed(1);
379:     return String(Math.floor(n));
380:   }
381:   const units = ['K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp'];
382:   let i = -1;
383:   let v = n;
384:   while (Math.abs(v) >= 1000 && i < units.length - 1) { v /= 1000; i++; }
385:   const dec = Math.abs(v) >= 100 ? 0 : Math.abs(v) >= 10 ? 1 : 2;
386:   return `${v.toFixed(dec).replace(/\.0+$/, '')}${units[i]}`;
387: }
388: 
389: export function fmtRate(n) {
390:   if (n === 0) return '0.00/s';
391:   if (n < 1) return `${n.toFixed(2)}/s`;
392:   return `${fmt(n, 1)}/s`;
393: }
