402: export function canAfford(state, cost) {
403:   for (const [k, v] of Object.entries(cost)) {
404:     if (k === 'caps') { if ((state.caps || 0) < v) return false; }
405:     else if ((state.ores[k] || 0) < v) return false;
406:   }
407:   return true;
408: }
