149:     state.stats.totalMined += amount;
150:     total += amount;
151:   });
152:   const stats = playerStats(state);
153:   state.combat.hp = Math.min(stats.maxHp, state.combat.hp + stats.maxHp * 0.01 * elapsed);
154:   if (state.combat.deadUntil < now) state.combat.deadUntil = 0;
155:   if (total <= 0) return null;
156:   return { seconds: elapsed, gains, total };
157: }
