244:   bind() {
245:     document.addEventListener('click', (e) => {
246:       const target = e.target.closest('[data-action]');
247:       if (target) {
248:         const action = target.dataset.action;
249:         const index = Number(target.dataset.index || 0);
250:         this.dispatch(action, index, target);
251:         return;
252:       }
253:       const tab = e.target.closest('[data-tab]');
254:       if (tab) {
255:         this.setTab(tab.dataset.tab);
256:         return;
257:       }
258:       if (e.target.closest('#soundBtn')) {
259:         this.game.toggleSound();
260:         return;
261:       }
262:       if (e.target.closest('#resetBtn')) {
263:         this.game.confirmReset();
264:       }
265:     });
266: 
267:     document.addEventListener('keydown', (e) => {
268:       if (e.repeat) return;
269:       if (e.code === 'Space') {
270:         e.preventDefault();
271:         if (document.getElementById('app').dataset.tab === 'mine' || window.innerWidth > 980) this.game.strikeMine();
272:       } else if (e.key === 'f' || e.key === 'F') {
273:         if (document.getElementById('app').dataset.tab === 'fight' || window.innerWidth > 980) this.game.attack();
274:       }
275:     });
276: 
277:     window.addEventListener('resize', () => {
278:       this.game.mineRenderer?.resize();
279:       this.game.combatRenderer?.resize();
280:     });
281: 
282:     // The scene canvases are the primary input on touch devices.
283:     $('mineScene')?.addEventListener('pointerdown', (e) => {
284:       if (e.target.closest('[data-action]')) return;
285:       this.game.strikeMine();
286:     });
287:     $('arena')?.addEventListener('pointerdown', (e) => {
288:       if (e.target.closest('[data-action]') || e.target.closest('.death-banner')) return;
289:       this.game.attack();
290:     });
291:   }
