293:   dispatch(action, index, target) {
294:     const g = this.game;
295:     switch (action) {
296:       case 'strike': g.strikeMine(); break;
297:       case 'attack': g.attack(); break;
298:       case 'auto': g.toggleAuto(); break;
299:       case 'pickaxe': g.buyPickaxe(); break;
300:       case 'crew': g.buyCrew(); break;
301:       case 'weapon': g.buyWeapon(); break;
302:       case 'armor': g.buyArmor(); break;
303:       case 'stim': g.buyStim(); break;
304:       case 'drill': g.buyDrill(index); break;
305:       case 'layer': g.selectLayer(index); break;
306:       case 'zone': g.selectZone(index); break;
307:       case 'outfit': g.buyOutfit(index); break;
308:       case 'attr': g.spendPoint(target?.dataset.id); break;
309:       case 'perks': g.openPerks(); break;
310:       case 'respec': g.respec(); break;
311:       case 'overload': g.confirmOverload(); break;
312:       default: break;
313:     }
314:   }
