559:   renderFight() {
560:     const s = this.s;
561:     const c = s.combat;
562:     const r = this.refs;
563:     const zone = ZONES[c.zone] || ZONES[0];
564:     const stats = playerStats(s);
565:     const enemy = c.enemy;
566:     const dead = c.deadUntil > Date.now();
567: 
568:     setText(r.zoneBadge, zone.name.toUpperCase());
569:     setText(r.zoneProgress, `${c.unlocked} / ${ZONES.length} SECURED`);
570:     setText(r.wavePill, enemy ? `${enemy.boss ? 'BOSS · ' : ''}WAVE ${c.waves[c.zone] || 1}` : `WAVE ${c.waves[c.zone] || 1}`);
571:     r.wavePill.classList.toggle('boss', !!enemy?.boss);
572:     if (enemy) {
573:       setText(r.enemyName, enemy.name.toUpperCase());
574:       r.enemyName.style.color = enemy.boss ? '#ffb15c' : '';
575:       const pct = Math.max(0, Math.min(100, (enemy.hp / Math.max(1, enemy.maxHp)) * 100));
576:       r.enemyBar.style.width = `${pct}%`;
577:       r.enemyBar.style.filter = enemy.boss ? 'saturate(1.3)' : '';
578:     } else {
579:       setText(r.enemyName, 'SCANNING…');
580:       r.enemyBar.style.width = '0%';
