passiveGain(dt) {
  const s = this.state;
  for (let i = 0; i < LAYERS.length; i++) {
    const count = s.drills[i] || 0;
    if (!count) continue;
    const ore = LAYERS[i].ore;
    const amount = count * drillRate(s, i) * dt;
    s.ores[ore] += amount;
    s.stats.totalMined += amount;
  }
}

