  const tool = miningTool(this.state);
  if (now - this.lastStrike < tool.cooldown) return;
  this.lastStrike = now;
  const s = this.state;
  const i = s.layer;
  const layer = LAYERS[i];
  const yieldAmt = strikeYield(s, i);
  const crit = Math.random() < 0.07 + tool.critBonus;
