  }
  if ((s.stats.clicks || 0) === 1) {
    this.log('First swing. Keep the tool moving — the vein gives more the deeper you go.', 'good');
  }
  this.gainXp(1 + (broke ? 12 + i * 2 : 0));
  if (!auto) this.ui.render();
}

