export const MAX_INVENTORY = 30;

export const RARITIES = [
  { id: 'common', name: 'Common', color: '#9aa8b2', rank: 0, prefix: 'Scavenged', affixes: 1 },
  { id: 'uncommon', name: 'Uncommon', color: '#7fdc6a', rank: 1, prefix: 'Riveted', affixes: 2 },
