84:   tick(now) {
85:     const dt = Math.min(1.5, Math.max(0, (now - this.lastTick) / 1000));
86:     this.lastTick = now;
87:     this.passiveGain(dt);
88:     this.tickMining(now);
89:     this.tickCombat(now, dt);
90:     if (now - this.lastUI > 150) {
91:       this.ui.render();
92:       this.lastUI = now;
93:     }
94:     if (now - this.lastSave > 5000) {
95:       this.saveNow();
96:       this.lastSave = now;
97:     }
98:   }
