100:   passiveGain(dt) {
101:     const s = this.state;
102:     for (let i = 0; i < LAYERS.length; i++) {
103:       const count = s.drills[i] || 0;
104:       if (!count) continue;
105:       const ore = LAYERS[i].ore;
106:       const amount = count * drillRate(s, i) * dt;
107:       s.ores[ore] += amount;
108:       s.stats.totalMined += amount;
109:     }
110:     const caps = salvageCapsRate(s) * dt;
111:     if (caps > 0) {
112:       s.caps += caps;
113:       s.stats.totalCaps = (s.stats.totalCaps || 0) + caps;
114:     }
115:   }
