136:   strikeMine(auto = false, now = performance.now()) {
137:     const tool = miningTool(this.state);
138:     if (now - this.lastStrike < tool.cooldown) return;
139:     this.lastStrike = now;
140:     const s = this.state;
141:     const i = s.layer;
142:     const layer = LAYERS[i];
143:     const yieldAmt = strikeYield(s, i);
144:     const crit = Math.random() < 0.07 + tool.critBonus;
145:     const gained = yieldAmt * (crit ? 3 : 1);
146:     s.ores[layer.ore] += gained;
147:     s.stats.totalMined += gained;
148:     s.stats.clicks = (s.stats.clicks || 0) + 1;
149: 
150:     const dmg = pickPower(s);
151:     const maxHp = layerMaxHp(s, i);
152:     s.veinHp[i] = (s.veinHp[i] ?? maxHp) - dmg;
153:     let broke = false;
154:     if (s.veinHp[i] <= 0) {
155:       broke = true;
156:       const bonus = yieldAmt * 10;
157:       s.ores[layer.ore] += bonus;
158:       s.stats.totalMined += bonus;
159:       s.nodes[i] = (s.nodes[i] || 0) + 1;
160:       s.veinHp[i] = layerMaxHp(s, i);
161:       this.mineRenderer.veinBreak();
162:       if (!auto) {
163:         this.audio.shatter();
164:         this.log(`Vein shattered. Richness ×${(1 + 0.04 * s.nodes[i]).toFixed(2)} · +${fmt(bonus)} ${ORES[layer.ore].name}.`, 'good');
165:       }
166:     } else if (!auto || Math.random() < 0.35) {
167:       this.audio[crit ? 'crit' : 'strike']();
168:     }
169:     this.mineRenderer.strike();
170:     if (!auto || broke || crit) this.mineRenderer.floatOre(Math.round(gained), layer.ore, crit);
171:     if (broke && !auto) {
172:       this.mineRenderer.floatOre(Math.round(yieldAmt * 10), layer.ore, true);
173:       this.ui.toast(`VEIN SHATTERED · +${fmt(Math.round(yieldAmt * 10))} ${ORES[layer.ore].name}`, 'good');
174:     } else if (crit && !auto) {
175:       this.ui.toast(`CRITICAL SEAM · +${fmt(Math.round(gained))} ${ORES[layer.ore].name}`, 'good');
176:     }
177:     if ((s.stats.clicks || 0) === 1) {
178:       this.log('First swing. Keep the tool moving — the vein gives more the deeper you go.', 'good');
179:     }
180:     this.gainXp(1 + (broke ? 12 + i * 2 : 0));
181:     if (!auto) this.ui.render();
182:   }
