184:   /* ── RPG progression ─────────────────────────────────────── */
185:   gainXp(amount) {
186:     const s = this.state;
187:     const mult = xpMultiplier(s);
188:     s.xp = (s.xp || 0) + Math.max(0, amount) * mult;
189:     let levels = 0;
190:     let perks = 0;
191:     let guard = 0;
192:     while (s.xp >= xpNeeded(s.level || 1) && guard++ < 100) {
193:       s.xp -= xpNeeded(s.level || 1);
194:       s.level = (s.level || 1) + 1;
195:       s.points = (s.points || 0) + 3;
196:       levels += 1;
197:       if (s.level % 3 === 0) {
198:         s.perkPoints = (s.perkPoints || 0) + 1;
199:         perks += 1;
200:       }
201:     }
202:     if (levels > 0) {
203:       const stats = playerStats(s);
204:       s.combat.hp = stats.maxHp;
205:       this.audio.levelUp();
206:       this.combatRenderer.levelUp();
207:       const perkText = perks > 0 ? ` · +${perks} PERK CHOICE${perks > 1 ? 'S' : ''}` : '';
208:       this.ui.toast(`LEVEL ${s.level} · +${levels * 3} ATTRIBUTE POINTS${perkText}`, 'lore');
209:       this.log(`Survivor reached level ${s.level}. +${levels * 3} attribute points${perks > 0 ? ' and a perk choice' : ''}.`, 'good');
210:       this.ui.render();
211:       this.saveNow();
212:     }
213:   }
