484:   /* ── combat ──────────────────────────────────────────────── */
485:   tickCombat(now, dt) {
486:     const s = this.state;
487:     const c = s.combat;
488:     const stats = playerStats(s);
489: 
490:     if (c.deadUntil > 0) {
491:       if (now >= c.deadUntil) {
492:         c.deadUntil = 0;
493:         c.hp = stats.maxHp;
494:         c.enemy = makeEnemy(c.zone, c.waves[c.zone]);
495:         c.enemy.nextAttack = now + c.enemy.interval;
496:         c.nextPlayerAttack = 0;
497:         this.nextSpawn = 0;
498:         this.combatRenderer.respawn();
499:         this.log('Reboot complete. Back on your feet.', '');
500:       }
501:       return;
502:     }
503: 
504:     if (!c.enemy) {
505:       if (now >= this.nextSpawn) {
506:         c.enemy = makeEnemy(c.zone, c.waves[c.zone]);
507:         c.enemy.nextAttack = now + c.enemy.interval * 0.9;
508:       } else {
509:         return;
510:       }
511:     }
512: 
513:     const enemy = c.enemy;
514:     c.hp = Math.min(stats.maxHp, c.hp + stats.maxHp * 0.007 * dt);
515: 
516:     if (c.auto && now >= (c.nextPlayerAttack || 0)) this.attack(now, true);
517: 
518:     if (c.enemy && now >= (c.enemy.nextAttack || 0) && c.deadUntil === 0) {
519:       const live = c.enemy;
520:       live.nextAttack = now + live.interval;
521:       this.combatRenderer.enemyAttack();
522:       this.audio.hurt();
523:       const dmg = live.dmg * (1 - stats.defense);
524:       c.hp -= dmg;
525:       this.combatRenderer.hurtNumber(dmg);
526:       this.combatRenderer.playerHit();
527:       if (c.hp <= 0) this.playerDied(now, stats);
528:     }
529:   }
