531:   attack(now = performance.now(), auto = false) {
532:     const s = this.state;
533:     const c = s.combat;
534:     if (c.deadUntil > 0 || !c.enemy) return;
535:     if (now < (c.nextPlayerAttack || 0)) return;
536:     c.nextPlayerAttack = now + playerAttackInterval(s);
537:     const stats = playerStats(s);
538:     const crit = Math.random() < stats.crit;
539:     const dmg = stats.attack * (0.9 + Math.random() * 0.2) * (crit ? 1.9 : 1);
540:     c.enemy.hp -= dmg;
541:     this.combatRenderer.playerAttack();
542:     this.combatRenderer.enemyHit();
543:     this.combatRenderer.damageNumber(dmg, crit);
544:     if (crit) this.audio.crit(); else this.audio.hit();
545: 
546:     if (c.enemy.hp <= 0) this.killEnemy(now, stats);
547:     this.ui.render();
548:   }
