550:   killEnemy(now, stats) {
551:     const s = this.state;
552:     const c = s.combat;
553:     const enemy = c.enemy;
554:     const zone = ZONES[c.zone];
555:     const caps = Math.max(1, Math.round(enemy.caps * (stats.capsMult || 1)));
556:     const oreAmt = Math.max(1, Math.round(enemy.oreAmt * (stats.oreMult || 1)));
557:     const xp = enemy.xp || 5;
558:     s.caps += caps;
559:     s.ores[enemy.ore] = (s.ores[enemy.ore] || 0) + oreAmt;
560:     s.stats.totalCaps = (s.stats.totalCaps || 0) + caps;
561:     s.stats.totalMined += oreAmt;
562:     s.stats.kills = (s.stats.kills || 0) + 1;
563:     s.combat.hp = Math.min(stats.maxHp, s.combat.hp + stats.healPerKill);
564:     c.waves[c.zone] = (c.waves[c.zone] || 1) + 1;
565: 
566:     this.combatRenderer.enemyKilled(c.zone, enemy.boss);
567:     this.audio.kill();
568:     this.gainXp(xp);
