325:   dispatch(action, index, target) {
326:     const g = this.game;
327:     switch (action) {
328:       case 'strike': g.strikeMine(); break;
329:       case 'attack': g.attack(); break;
330:       case 'auto': g.toggleAuto(); break;
331:       case 'automine': g.toggleAutoMine(); break;
332:       case 'equiptool': g.equipTool(target?.dataset.id); break;
333:       case 'equipweapon': g.equipWeapon(target?.dataset.id); break;
334:       case 'pickaxe': g.buyPickaxe(); break;
335:       case 'crew': g.buyCrew(); break;
336:       case 'weapon': g.buyWeapon(); break;
337:       case 'armor': g.buyArmor(); break;
338:       case 'stim': g.buyStim(); break;
339:       case 'drill': g.buyDrill(index); break;
340:       case 'layer': g.selectLayer(index); break;
341:       case 'zone': g.selectZone(index); break;
342:       case 'outfit': g.buyOutfit(index); break;
343:       case 'attr': g.spendPoint(target?.dataset.id); break;
344:       case 'perks': g.openPerks(); break;
345:       case 'respec': g.respec(); break;
346:       case 'overload': g.confirmOverload(); break;
347:       default: break;
348:     }
349:   }
