656:   renderFight() {
657:     const s = this.s;
658:     const c = s.combat;
659:     const r = this.refs;
660:     const zone = ZONES[c.zone] || ZONES[0];
661:     const stats = playerStats(s);
662:     const enemy = c.enemy;
663:     const perfNow = performance.now();
664:     const dead = c.deadUntil > perfNow;
665: 
666:     setText(r.zoneBadge, zone.name.toUpperCase());
667:     setText(r.zoneProgress, `${c.unlocked} / ${ZONES.length} SECURED`);
668:     setText(r.wavePill, enemy ? `${enemy.boss ? 'BOSS · ' : ''}WAVE ${c.waves[c.zone] || 1}` : `WAVE ${c.waves[c.zone] || 1}`);
669:     r.wavePill.classList.toggle('boss', !!enemy?.boss);
670:     if (enemy) {
671:       setText(r.enemyName, enemy.name.toUpperCase());
672:       r.enemyName.style.color = enemy.boss ? '#ffb15c' : '';
673:       const pct = Math.max(0, Math.min(100, (enemy.hp / Math.max(1, enemy.maxHp)) * 100));
674:       r.enemyBar.style.width = `${pct}%`;
675:       r.enemyBar.style.filter = enemy.boss ? 'saturate(1.3)' : '';
676:     } else {
677:       setText(r.enemyName, 'SCANNING…');
678:       r.enemyBar.style.width = '0%';
679:     }
680:     const hpPct = Math.max(0, Math.min(100, (c.hp / stats.maxHp) * 100));
681:     r.playerBar.style.width = `${hpPct}%`;
682:     setText(r.playerHpText, `${fmt(Math.max(0, c.hp))} / ${fmt(stats.maxHp)}`);
683:     setText(r.playerLevel, String(s.level || 1));
684:     const need = xpNeeded(s.level || 1);
685:     r.playerXpBar.style.width = `${Math.max(0, Math.min(100, ((s.xp || 0) / need) * 100))}%`;
686:     setText(r.playerXpText, `${fmt(s.xp || 0, 0)}/${fmt(need)}`);
687:     setText(r.atkStat, fmt(stats.attack, 1));
688:     setText(r.defStat, `${Math.round(stats.defense * 100)}%`);
689:     setText(r.killStat, fmt(s.stats.kills || 0));
690:     r.deathBanner.hidden = !dead;
691:     if (dead) setText(r.deathBanner, `FLATLINED — REBOOTING ${Math.max(1, Math.ceil((c.deadUntil - perfNow) / 1000))}s`);
692:     r.autoBtn.classList.toggle('on', !!c.auto);
693:     r.autoBtn.setAttribute('aria-pressed', String(!!c.auto));
694:     setText(r.autoLabel, c.auto ? 'AUTO: ON' : 'AUTO: OFF');
695:     const cooling = perfNow < (c.nextPlayerAttack || 0);
696:     r.attackBtn.classList.toggle('cooling', cooling && !dead);
697: 
698:     this.zoneEls.forEach(({ btn, name, sub, status }, i) => {
699:       const z = ZONES[i];
700:       const unlocked = i < c.unlocked;
701:       btn.classList.toggle('locked', !unlocked);
702:       btn.classList.toggle('active', i === c.zone);
703:       name.querySelector('.z-dot').style.background = unlocked ? z.accent : '#4a4f43';
704:       name.querySelector('.z-dot').style.boxShadow = unlocked ? `0 0 6px ${z.accent}` : 'none';
705:       if (unlocked) {
706:         btn.classList.remove('ready');
707:         sub.textContent = `${z.unlock ? `${z.baseHp} HP` : 'STARTING GROUND'} · WAVE ${c.waves[i]} · ~${fmt(z.caps)} caps/kill`;
708:         if (i === c.zone) {
709:           status.innerHTML = `<b>ACTIVE</b>${z.enemies[0]}`;
710:           status.classList.add('active-tag');
711:         } else {
712:           status.innerHTML = `<b>TRAVEL</b>WAVE ${c.waves[i]}`;
713:           status.classList.remove('active-tag');
714:         }
715:       } else {
716:         const req = z.unlock;
717:         const ready = canAfford(s, { caps: req.caps, ...req.ore });
718:         btn.classList.toggle('ready', ready);
719:         status.classList.remove('active-tag');
720:         sub.textContent = `${z.baseDmg} DMG · ${fmt(z.caps)} caps/kill · ${ORES[z.ore].name}`;
721:         status.innerHTML = ready ? `<b>UNLOCK</b>${fmt(req.caps)} CAPS` : `<b>LOCKED</b>${fmt(req.caps)} CAPS`;
722:       }
723:     });
724:   }
