529:   drawDrillRig(ctx, t, layer, drills) {
530:     if (!drills || drills <= 0) return;
531:     const x = this.w * 0.155;
532:     const y = this.floorY + 3;
533:     const s = this.scale * 0.84;
534:     const speed = 2.4 + Math.min(4, drills * 0.16);
535:     const piston = (Math.sin(t * speed) + 1) / 2;
536:     ctx.save();
537:     ctx.translate(x, y);
538:     ctx.scale(s, s);
539: 
540:     // shadow
541:     ctx.fillStyle = 'rgba(0,0,0,0.45)';
542:     ctx.beginPath(); ctx.ellipse(0, 0, 38, 7, 0, 0, TAU); ctx.fill();
543: 
544:     // ore pile
545:     ctx.fillStyle = rgba(layer.glow, 0.35);
546:     for (let i = 0; i < 5; i++) {
547:       ctx.beginPath();
548:       ctx.arc(-30 + i * 9, -4 - (i % 2) * 3, 4 + (i % 3), 0, TAU);
549:       ctx.fill();
550:     }
551: 
552:     // base
553:     ctx.fillStyle = '#1b1d17';
554:     ctx.fillRect(-26, -14, 52, 13);
555:     ctx.fillStyle = '#2a2c24';
556:     ctx.fillRect(-26, -16, 52, 4);
557:     ctx.strokeStyle = 'rgba(255,255,255,0.07)';
558:     ctx.strokeRect(-26, -14, 52, 13);
559: 
560:     // mast
561:     ctx.strokeStyle = '#31352b';
562:     ctx.lineWidth = 5;
563:     ctx.beginPath();
564:     ctx.moveTo(-14, -16); ctx.lineTo(-7, -64);
565:     ctx.moveTo(14, -16); ctx.lineTo(7, -64);
566:     ctx.stroke();
567:     ctx.lineWidth = 2;
568:     ctx.strokeStyle = '#454a3b';
569:     ctx.beginPath();
570:     ctx.moveTo(-19, -30); ctx.lineTo(17, -44);
571:     ctx.moveTo(-18, -44); ctx.lineTo(16, -30);
572:     ctx.stroke();
573: 
574:     // piston
575:     const py = -30 - piston * 26;
576:     ctx.strokeStyle = '#5c6250';
577:     ctx.lineWidth = 4;
578:     ctx.beginPath(); ctx.moveTo(0, -62); ctx.lineTo(0, py); ctx.stroke();
579:     ctx.fillStyle = '#363b2f';
580:     ctx.fillRect(-9, py, 18, 11);
581:     ctx.fillStyle = '#1c1f18';
582:     ctx.fillRect(-11, py + 8, 22, 4);
583: 
584:     // spinning flywheel
585:     ctx.save();
586:     ctx.translate(17, -24);
587:     ctx.rotate(t * speed * 0.9);
588:     ctx.strokeStyle = '#4a5040';
589:     ctx.lineWidth = 2;
590:     ctx.beginPath(); ctx.arc(0, 0, 7, 0, TAU); ctx.stroke();
591:     for (let i = 0; i < 3; i++) {
592:       const a = i * TAU / 3;
593:       ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(Math.cos(a) * 6, Math.sin(a) * 6); ctx.stroke();
594:     }
595:     ctx.restore();
596: 
597:     // lamp
598:     const blink = Math.sin(t * (3 + drills * 0.2)) > 0.65;
599:     ctx.fillStyle = blink ? '#ffb15c' : '#5a3a1e';
600:     ctx.beginPath(); ctx.arc(0, -68, 2.5, 0, TAU); ctx.fill();
