659:   drawVein(ctx, t, layer, state, layerIndex, node, key) {
660:     if (this.veinHidden > 0) return;
661:     const { veinX: cx, veinY: cy, scale: s } = this;
662:     const hp = state.veinHp?.[layerIndex] ?? layer.hp;
663:     const maxHp = layerMaxHp(state, layerIndex);
664:     const dmg = clamp(1 - hp / Math.max(1, maxHp), 0, 1);
665:     const pulse = 0.82 + Math.sin(t * 2.3) * 0.18;
666:     const rich = 1 + 0.02 * node;
667: 
668:     ctx.save();
669:     ctx.translate(cx, cy + Math.sin(t * 1.7) * 1.5);
670:     ctx.scale(s * rich, s * rich);
671: 
672:     // base glow
673:     const glow = layer.glow;
674:     const gg = ctx.createRadialGradient(0, 0, 2, 0, 0, 78);
675:     gg.addColorStop(0, rgba(glow, 0.22 * pulse));
676:     gg.addColorStop(0.5, rgba(glow, 0.06));
677:     gg.addColorStop(1, 'rgba(0,0,0,0)');
678:     ctx.fillStyle = gg;
679:     ctx.fillRect(-90, -90, 180, 180);
680: 
681:     // rock base
682:     ctx.fillStyle = '#161611';
683:     ctx.beginPath();
684:     ctx.moveTo(-34, 30); ctx.lineTo(-28, 12); ctx.lineTo(-10, 4);
685:     ctx.lineTo(8, 8); ctx.lineTo(28, 2); ctx.lineTo(35, 30);
686:     ctx.closePath();
687:     ctx.fill();
688:     ctx.strokeStyle = 'rgba(255,255,255,0.05)';
689:     ctx.stroke();
690: 
691:     // crystals
692:     const crystals = this.crystals || [];
693:     for (const c of crystals) {
694:       ctx.save();
695:       ctx.translate(c.x, c.y);
696:       ctx.rotate(c.rot);
697:       const col = mixHex(glow, '#ffffff', 0.1 + c.tone * 0.16);
698:       ctx.shadowColor = rgba(glow, 0.7);
699:       ctx.shadowBlur = 14;
700:       ctx.beginPath();
701:       ctx.moveTo(0, -c.len * 0.55);
702:       ctx.lineTo(c.wid, 0);
703:       ctx.lineTo(0, c.len * 0.5);
704:       ctx.lineTo(-c.wid, 0);
705:       ctx.closePath();
706:       ctx.fillStyle = rgba(col, 0.22 + 0.3 * c.tone);
707:       ctx.fill();
708:       ctx.shadowBlur = 0;
709:       ctx.strokeStyle = rgba(mixHex(glow, '#ffffff', 0.5), 0.5);
710:       ctx.lineWidth = 0.9;
711:       ctx.stroke();
712:       // facets
713:       ctx.beginPath();
714:       ctx.moveTo(0, -c.len * 0.5);
715:       ctx.lineTo(0, c.len * 0.45);
716:       ctx.strokeStyle = rgba('#ffffff', 0.16);
717:       ctx.stroke();
718:       ctx.restore();
719:     }
720: 
721:     // cracks as integrity drops
722:     const cracks = Math.floor(dmg * 6);
723:     if (cracks > 0) {
724:       ctx.strokeStyle = 'rgba(10,8,6,0.65)';
725:       ctx.lineWidth = 1.4;
726:       const rnd = mulberry32(500 + layerIndex * 37 + node * 7);
727:       for (let i = 0; i < cracks; i++) {
728:         let x = (rnd() - 0.5) * 40;
729:         let y = (rnd() - 0.5) * 30;
730:         ctx.beginPath();
731:         ctx.moveTo(x, y);
732:         for (let k = 0; k < 3; k++) {
733:           x += (rnd() - 0.5) * 16;
734:           y += (rnd() - 0.5) * 14;
735:           ctx.lineTo(x, y);
736:         }
737:         ctx.stroke();
738:       }
739:     }
740: 
741:     // node pulse ring
742:     if (this.nodePulse > 0) {
743:       ctx.globalAlpha = this.nodePulse;
744:       ctx.strokeStyle = rgba(glow, 0.6);
745:       ctx.lineWidth = 1.5;
746:       ctx.beginPath();
747:       ctx.arc(0, 0, 40 + (1 - this.nodePulse) * 50, 0, TAU);
748:       ctx.stroke();
749:       ctx.globalAlpha = 1;
750:     }
751:     ctx.restore();
752:   }
