754:   drawMiner(ctx, t, layer) {
755:     const s = this.scale;
756:     const baseX = this.minerX;
757:     const floorY = this.floorY;
758:     const outfits = this.game.state.outfits || {};
759:     const duster = outfits.duster || 0;
760:     const rebreather = outfits.rebreather || 0;
761:     const charm = outfits.charm || 0;
762:     const coatColor = outfitCoat(duster);
763:     const goggleColor = outfitGoggles(rebreather);
764:     const p = this.swing;
765:     let swingAngle;
766:     if (p >= 1) swingAngle = -0.62;
767:     else if (p < 0.22) swingAngle = lerp(-0.62, -1.95, easeOut(p / 0.22));
768:     else if (p < 0.46) swingAngle = lerp(-1.95, 0.5, easeInOut((p - 0.22) / 0.24));
769:     else swingAngle = lerp(0.5, -0.62, easeInOut((p - 0.46) / 0.54));
