848:     // shoulder pad
849:     ctx.fillStyle = '#2b2318';
850:     ctx.beginPath(); ctx.arc(-2, -58, 8, Math.PI, TAU); ctx.fill();
851:     ctx.strokeStyle = 'rgba(255,177,92,0.25)'; ctx.stroke();
