913:     ctx.beginPath();
914:     ctx.moveTo(handX, handY - 1);
915:     ctx.lineTo(tipX, tipY - 1);
916:     ctx.stroke();
917:     // axe head
918:     ctx.save();
919:     ctx.translate(tipX, tipY);
920:     ctx.rotate(swingAngle + Math.PI / 2);
921:     ctx.fillStyle = '#7c7d6e';
922:     ctx.beginPath();
923:     ctx.moveTo(-8, 0); ctx.lineTo(0, -5); ctx.lineTo(8, 0); ctx.lineTo(5, 4); ctx.lineTo(-5, 4);
924:     ctx.closePath();
925:     ctx.fill();
926:     ctx.strokeStyle = 'rgba(255,255,255,0.32)';
927:     ctx.lineWidth = 1;
928:     ctx.stroke();
929:     ctx.fillStyle = 'rgba(255,177,92,0.35)';
930:     ctx.beginPath(); ctx.moveTo(-3, -2); ctx.lineTo(0, -4); ctx.lineTo(3, -2); ctx.closePath(); ctx.fill();
931:     ctx.restore();
932: 
933:     // impact spark ring
934:     if (p > 0.35 && p < 0.55) {
935:       const k = (p - 0.35) / 0.2;
936:       ctx.globalAlpha = 1 - k;
937:       ctx.strokeStyle = 'rgba(255,220,170,0.85)';
938:       ctx.lineWidth = 2;
939:       ctx.beginPath();
940:       ctx.arc(tipX + 4, tipY, 4 + k * 20, 0, TAU);
941:       ctx.stroke();
942:       ctx.globalAlpha = 1;
943:     }
944: 
945:     ctx.restore();
946:   }
947: 
948:   updateParticles(dt) {
949:     for (let i = this.particles.length - 1; i >= 0; i--) {
950:       const p = this.particles[i];
951:       p.life -= dt;
952:       if (p.life <= 0) { this.particles.splice(i, 1); continue; }
953:       p.vy += (p.gravity || 0) * dt;
954:       p.x += p.vx * dt;
955:       p.y += p.vy * dt;
956:     }
957:   }
958: 
959:   drawParticles(ctx) {
960:     for (const p of this.particles) {
961:       const a = clamp(p.life / (p.max || 1), 0, 1);
962:       ctx.globalAlpha = a;
963:       ctx.fillStyle = p.color;
964:       ctx.beginPath();
965:       ctx.arc(p.x, p.y, p.size, 0, TAU);
966:       ctx.fill();
967:     }
968:     ctx.globalAlpha = 1;
969:   }
970: 
971:   drawFloats(dt, ctx) {
972:     for (let i = this.floats.length - 1; i >= 0; i--) {
973:       const f = this.floats[i];
974:       f.life -= dt;
975:       if (f.life <= 0) { this.floats.splice(i, 1); continue; }
976:       f.y += f.vy * dt;
977:       f.vy *= 0.96;
978:       const a = clamp(f.life / (f.max || 1), 0, 1);
979:       ctx.globalAlpha = a;
980:       ctx.font = `700 ${f.size}px ui-monospace, monospace`;
981:       ctx.textAlign = 'center';
982:       ctx.lineWidth = 3;
983:       ctx.strokeStyle = 'rgba(0,0,0,0.75)';
984:       ctx.strokeText(f.text, f.x, f.y);
985:       ctx.fillStyle = f.color;
986:       ctx.fillText(f.text, f.x, f.y);
987:       ctx.globalAlpha = 1;
988:     }
989:     ctx.textAlign = 'left';
990:   }
991: }
