1000: export class CombatRenderer extends BaseRenderer {
1001:   constructor(canvas, game) {
1002:     super(canvas, game);
1003:     this.playerAtk = 1;
1004:     this.enemyAtk = 1;
1005:     this.enemyFlash = 0;
1006:     this.playerHurt = 0;
1007:     this.shake = 0;
1008:     this.floats = [];
1009:     this.particles = [];
1010:     this.spawnAt = 0;
1011:     this.enemyKey = '';
1012:     this.lastZone = -1;
1013:     this.env = null;
1014:     this.fallen = false;
1015:     this.fallT = 0;
1016:     this.targetFlash = 0;
1017:     this.levelFx = 0;
1018:   }
1019: 
1020:   onResize() {
1021:     this.floorY = this.h * 0.80;
1022:     this.scale = clamp(this.h / 280, 0.72, 1.35);
1023:     this.playerX = this.w * 0.27;
1024:     this.enemyX = this.w * 0.74;
1025:     this.buildEnv(this.game.state.combat.zone || 0);
1026:   }
1027: 
1028:   buildEnv(zoneIndex) {
1029:     const zone = ZONES[zoneIndex] || ZONES[0];
1030:     const rnd = mulberry32(1900 + zoneIndex * 71);
1031:     const buildings = [];
1032:     let x = -20;
1033:     while (x < this.w + 60) {
1034:       const bw = 24 + rnd() * 65;
1035:       const bh = 20 + rnd() * 95;
1036:       buildings.push({
1037:         x, w: bw, h: bh,
1038:         notch: rnd() < 0.35, antenna: rnd() < 0.22,
1039:         windows: Array.from({ length: Math.floor(rnd() * 3) }, () => ({
1040:           x: rnd(), y: rnd(), lit: rnd() < 0.55, phase: rnd() * 10,
1041:         })),
1042:       });
1043:       x += bw + 4 + rnd() * 14;
1044:     }
1045:     this.env = { zone, buildings };
1046:     this.lastZone = zoneIndex;
1047:   }
1048: 
1049:   playerAttack() {
1050:     this.playerAtk = 0;
1051:     this.fallen = false;
1052:   }
1053: 
1054:   enemyAttack() {
1055:     this.enemyAtk = 0;
1056:   }
1057: 
1058:   enemyHit() {
1059:     this.enemyFlash = 1;
1060:     this.shake = Math.max(this.shake, 4);
1061:   }
1062: 
1063:   playerHit() {
1064:     this.playerHurt = 1;
1065:     this.shake = Math.max(this.shake, 8);
1066:   }
1067: 
1068:   enemyKilled(zoneIndex, boss) {
1069:     this.enemyFlash = 1;
1070:     this.shake = 12;
1071:     const color = ZONES[zoneIndex]?.enemy || '#a4633f';
1072:     for (let i = 0; i < (boss ? 50 : 26); i++) {
1073:       const a = Math.random() * TAU;
1074:       const sp = 25 + Math.random() * 150;
1075:       this.particles.push({
1076:         x: this.enemyX + (Math.random() - 0.5) * 30,
1077:         y: this.floorY - 40 - Math.random() * 50,
1078:         vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 40,
1079:         life: 0.5 + Math.random() * 0.8, max: 1.3,
1080:         size: 1 + Math.random() * 3, color: Math.random() < 0.3 ? '#ffb15c' : color,
1081:         gravity: 250,
1082:       });
1083:     }
1084:   }
1085: 
1086:   playerDied() {
1087:     this.fallen = true;
1088:     this.fallT = 0;
1089:     this.shake = 14;
1090:   }
1091: 
1092:   respawn() {
1093:     this.fallen = false;
1094:     this.fallT = 0;
1095:     this.playerAtk = 1;
1096:     this.enemyAtk = 1;
1097:   }
1098: 
1099:   levelUp() {
1100:     this.levelFx = 1;
1101:     this.addFloat('LEVEL UP', '#ffe9a8', this.playerX + 10, this.floorY - 105 * this.scale, 13);
1102:     for (let i = 0; i < 30; i++) {
1103:       const a = Math.random() * TAU;
1104:       const sp = 20 + Math.random() * 90;
1105:       this.particles.push({
1106:         x: this.playerX, y: this.floorY - 45 * this.scale,
1107:         vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 45,
1108:         life: 0.5 + Math.random() * 0.7, max: 1.2,
1109:         size: 1 + Math.random() * 2.4, color: i % 3 ? '#ffe9a8' : '#b7ee58',
1110:         gravity: -25,
1111:       });
1112:     }
1113:   }
1114: 
1115:   addFloat(text, color, x, y, size = 12) {
1116:     this.floats.push({ text, color, x, y, vy: -42, life: 0.95, max: 0.95, size });
1117:   }
1118: 
1119:   damageNumber(amount, crit = false) {
1120:     const x = this.enemyX + (Math.random() * 28 - 14);
1121:     const y = this.floorY - 80 * this.scale - Math.random() * 20;
1122:     this.floats.push({
1123:       text: crit ? `${Math.round(amount)}!` : `${Math.round(amount)}`,
1124:       color: crit ? '#fff1b8' : '#ffd8b8',
1125:       x, y, vy: -46, life: 0.9, max: 0.9, size: crit ? 18 : 13,
1126:     });
1127:   }
1128: 
1129:   hurtNumber(amount) {
1130:     this.floats.push({
1131:       text: `-${Math.round(amount)}`,
1132:       color: '#ff6f58',
1133:       x: this.playerX + 10, y: this.floorY - 78 * this.scale,
1134:       vy: -38, life: 0.85, max: 0.85, size: 12,
1135:     });
1136:   }
1137: 
1138:   draw(dt, t) {
1139:     const ctx = this.ctx;
1140:     const state = this.game.state;
1141:     const combat = state.combat;
1142:     const zoneIndex = combat.zone || 0;
1143:     const zone = ZONES[zoneIndex] || ZONES[0];
1144:     if (zoneIndex !== this.lastZone || !this.env) this.buildEnv(zoneIndex);
1145: 
1146:     this.playerAtk = Math.min(1, this.playerAtk + dt / 0.34);
1147:     this.enemyAtk = Math.min(1, this.enemyAtk + dt / 0.46);
1148:     this.enemyFlash = Math.max(0, this.enemyFlash - dt * 4.5);
1149:     this.playerHurt = Math.max(0, this.playerHurt - dt * 3);
1150:     this.levelFx = Math.max(0, this.levelFx - dt * 1.1);
1151:     this.shake = Math.max(0, this.shake - dt * 36);
1152:     if (this.fallen) this.fallT = Math.min(1, this.fallT + dt * 2.6);
1153: 
1154:     const enemy = combat.enemy;
1155:     const key = enemy ? `${zoneIndex}:${enemy.name}:${enemy.maxHp}:${enemy.boss}` : '';
1156:     if (key && key !== this.enemyKey) {
1157:       this.enemyKey = key;
1158:       this.spawnAt = t;
1159:       this.enemyFlash = 0;
1160:     }
1161:     const spawnAge = t - this.spawnAt;
1162: 
1163:     ctx.save();
1164:     if (this.shake > 0.3) ctx.translate((Math.random() - 0.5) * this.shake, (Math.random() - 0.5) * this.shake);
1165: 
1166:     this.drawSky(ctx, t, zone, zoneIndex);
1167:     this.drawSkyline(ctx, t);
1168:     this.drawGround(ctx, t);
1169:     this.drawArenaProps(ctx, t);
1170: 
1171:     // enemy aura for boss / sentry
1172:     if (enemy?.boss) {
1173:       const aura = ctx.createRadialGradient(this.enemyX, this.floorY - 50 * this.scale, 2, this.enemyX, this.floorY - 50 * this.scale, 90 * this.scale);
1174:       aura.addColorStop(0, rgba(zone.accent, 0.18 + Math.sin(t * 3) * 0.05));
1175:       aura.addColorStop(1, 'rgba(0,0,0,0)');
1176:       ctx.fillStyle = aura;
1177:       ctx.fillRect(this.enemyX - 110 * this.scale, this.floorY - 160 * this.scale, 220 * this.scale, 170 * this.scale);
1178:     }
1179: 
1180:     if (enemy) {
1181:       const p = this.enemyAtk;
1182:       const lunge = p < 1 ? -14 * Math.sin(Math.PI * p) * this.scale : 0;
1183:       const deathFade = enemy.hp <= 0 ? 1 : 0;
1184:       ctx.save();
1185:       const spawnK = clamp(spawnAge / 0.4, 0, 1);
1186:       ctx.globalAlpha = spawnK * (1 - deathFade);
1187:       const bounce = (1 - easeOut(spawnK)) * -14 * this.scale;
1188:       this.drawEnemy(ctx, enemy, zone, zoneIndex, t, this.enemyX + lunge, this.floorY + bounce, this.scale, spawnAge);
1189:       ctx.restore();
1190:     }
1191: 
1192:     // player
1193:     const pp = this.playerAtk;
1194:     const lunge = pp < 1 ? 15 * Math.sin(Math.PI * pp) * this.scale : 0;
1195:     if (this.levelFx > 0.02) {
1196:       const k = 1 - this.levelFx;
1197:       ctx.save();
1198:       ctx.globalAlpha = this.levelFx * 0.7;
1199:       ctx.strokeStyle = '#ffe9a8';
1200:       ctx.lineWidth = 2;
1201:       ctx.beginPath();
1202:       ctx.ellipse(this.playerX, this.floorY - 2, (20 + k * 55) * this.scale, (6 + k * 12) * this.scale, 0, 0, TAU);
1203:       ctx.stroke();
1204:       ctx.restore();
1205:     }
1206:     this.drawPlayer(ctx, t, this.playerX + lunge, this.floorY, this.scale);
1207: 
1208:     ctx.restore();
1209: 
1210:     this.updateParticles(dt);
1211:     this.drawParticles(ctx);
1212:     this.drawFloats(dt, ctx);
1213: 
1214:     if (this.playerHurt > 0.02) {
1215:       const hg = ctx.createRadialGradient(this.w * 0.5, this.h * 0.5, this.h * 0.25, this.w * 0.5, this.h * 0.5, this.h * 0.9);
1216:       hg.addColorStop(0, 'rgba(180,20,10,0)');
1217:       hg.addColorStop(1, `rgba(180,20,10,${0.3 * this.playerHurt})`);
1218:       ctx.fillStyle = hg;
1219:       ctx.fillRect(0, 0, this.w, this.h);
1220:     }
1221: 
1222:     // vignette
1223:     const v = ctx.createRadialGradient(this.w / 2, this.h / 2, this.h * 0.2, this.w / 2, this.h / 2, this.h * 0.9);
1224:     v.addColorStop(0, 'rgba(0,0,0,0)');
1225:     v.addColorStop(1, 'rgba(0,0,0,0.58)');
1226:     ctx.fillStyle = v;
1227:     ctx.fillRect(0, 0, this.w, this.h);
1228:   }
1229: 
1230:   drawSky(ctx, t, zone, zoneIndex) {
1231:     const { w, h } = this;
1232:     const g = ctx.createLinearGradient(0, 0, 0, h);
1233:     g.addColorStop(0, zone.sky[0]);
1234:     g.addColorStop(0.7, zone.sky[1]);
1235:     g.addColorStop(1, '#050504');
1236:     ctx.fillStyle = g;
1237:     ctx.fillRect(0, 0, w, h);
1238: 
1239:     // hazy sun
1240:     const sx = w * 0.76;
1241:     const sy = h * 0.2;
1242:     const sr = Math.min(w, h) * 0.09;
1243:     const sg = ctx.createRadialGradient(sx, sy, sr * 0.2, sx, sy, sr * 3.2);
1244:     sg.addColorStop(0, rgba(zone.accent, 0.20));
1245:     sg.addColorStop(0.35, rgba(zone.accent, 0.07));
1246:     sg.addColorStop(1, 'rgba(0,0,0,0)');
1247:     ctx.fillStyle = sg;
1248:     ctx.fillRect(sx - sr * 3.3, sy - sr * 3.3, sr * 6.6, sr * 6.6);
1249:     ctx.fillStyle = rgba(zone.accent, 0.18);
1250:     ctx.beginPath();
1251:     ctx.arc(sx, sy, sr, 0, TAU);
1252:     ctx.fill();
1253:     // cloud bands
1254:     ctx.save();
1255:     ctx.globalAlpha = 0.18;
1256:     for (let i = 0; i < 4; i++) {
1257:       const y = h * (0.12 + i * 0.07);
1258:       const offset = (t * (2 + i)) % (w + 200);
1259:       ctx.fillStyle = i % 2 ? zone.sky[0] : '#080706';
1260:       ctx.beginPath();
1261:       ctx.ellipse(w * 0.4 - 100 + offset - 100, y, w * 0.3, 6 + i * 2, 0, 0, TAU);
1262:       ctx.fill();
1263:     }
1264:     ctx.restore();
1265: 
1266:     // embers
1267:     for (let i = 0; i < 22; i++) {
1268:       const seed = i * 37.7;
1269:       const x = (seed * 13 + t * (5 + (i % 5) * 2)) % (w + 40) - 20;
1270:       const y = h * 0.8 - ((t * (8 + i % 7) + seed) % (h * 0.6));
1271:       const a = 0.1 + (i % 4) * 0.05;
1272:       ctx.fillStyle = i % 3 === 0 ? `rgba(255,177,92,${a})` : `rgba(200,200,180,${a * 0.6})`;
1273:       ctx.beginPath();
1274:       ctx.arc(x, y, 0.6 + (i % 3) * 0.5, 0, TAU);
1275:       ctx.fill();
1276:     }
1277:   }
1278: 
1279:   drawSkyline(ctx, t) {
1280:     if (!this.env) return;
1281:     const zone = this.env.zone;
1282:     for (const b of this.env.buildings) {
1283:       const base = this.floorY - this.scale * 24;
1284:       ctx.save();
1285:       ctx.fillStyle = 'rgba(4,4,3,0.72)';
1286:       ctx.beginPath();
1287:       ctx.moveTo(b.x, base);
1288:       ctx.lineTo(b.x, base - b.h);
1289:       if (b.notch) {
1290:         ctx.lineTo(b.x + b.w * 0.4, base - b.h);
1291:         ctx.lineTo(b.x + b.w * 0.4, base - b.h + 8);
1292:         ctx.lineTo(b.x + b.w * 0.6, base - b.h + 8);
1293:         ctx.lineTo(b.x + b.w * 0.6, base - b.h);
1294:       }
1295:       ctx.lineTo(b.x + b.w, base - b.h);
1296:       ctx.lineTo(b.x + b.w, base);
1297:       ctx.closePath();
1298:       ctx.fill();
1299:       if (b.antenna) {
1300:         ctx.strokeStyle = 'rgba(4,4,3,0.8)';
1301:         ctx.lineWidth = 1;
1302:         ctx.beginPath();
1303:         ctx.moveTo(b.x + b.w * 0.5, base - b.h);
1304:         ctx.lineTo(b.x + b.w * 0.5, base - b.h - 14 - (b.w % 17));
1305:         ctx.stroke();
1306:       }
1307:       for (const win of b.windows) {
1308:         if (!win.lit) continue;
1309:         const flick = 0.4 + 0.6 * Math.abs(Math.sin(t * 2 + win.phase));
1310:         ctx.fillStyle = `rgba(255,150,60,${0.18 * flick})`;
1311:         ctx.fillRect(b.x + win.x * b.w * 0.7 + 4, base - b.h + 6 + win.y * b.h * 0.5, 3, 3);
1312:       }
1313:       ctx.restore();
1314:     }
1315:     // distant smoke
1316:     ctx.save();
1317:     ctx.globalAlpha = 0.1;
1318:     for (let i = 0; i < 3; i++) {
1319:       const x = this.w * (0.2 + i * 0.28) + Math.sin(t * 0.2 + i) * 14;
1320:       ctx.fillStyle = '#0a0907';
1321:       ctx.beginPath();
1322:       ctx.ellipse(x, this.floorY - this.scale * (60 + i * 15), 40 + i * 12, 16 + i * 5, 0.2, 0, TAU);
1323:       ctx.fill();
1324:     }
1325:     ctx.restore();
1326:   }
1327: 
1328:   drawGround(ctx, t) {
1329:     const { w, h, floorY } = this;
1330:     const g = ctx.createLinearGradient(0, floorY, 0, h);
1331:     g.addColorStop(0, '#181510');
1332:     g.addColorStop(0.4, '#0d0c09');
1333:     g.addColorStop(1, '#050504');
1334:     ctx.fillStyle = g;
1335:     ctx.fillRect(0, floorY, w, h - floorY);
1336: 
1337:     // horizon line
1338:     ctx.strokeStyle = 'rgba(255,200,140,0.07)';
1339:     ctx.lineWidth = 1;
1340:     ctx.beginPath();
1341:     ctx.moveTo(0, floorY);
1342:     ctx.lineTo(w, floorY);
1343:     ctx.stroke();
1344: 
1345:     // perspective cracks
1346:     ctx.save();
1347:     ctx.strokeStyle = 'rgba(0,0,0,0.5)';
1348:     ctx.lineWidth = 1.4;
1349:     const rnd = mulberry32(44 + this.lastZone);
1350:     for (let i = 0; i < 6; i++) {
1351:       let x = rnd() * w;
1352:       let y = floorY + 6 + rnd() * (h - floorY - 10);
1353:       ctx.beginPath();
1354:       ctx.moveTo(x, y);
1355:       for (let k = 0; k < 4; k++) {
1356:         x += (rnd() - 0.5) * 40;
1357:         y += (rnd() - 0.5) * 8;
1358:         ctx.lineTo(x, y);
1359:       }
1360:       ctx.stroke();
1361:     }
1362:     // rubble
1363:     for (let i = 0; i < 12; i++) {
1364:       const x = rnd() * w;
1365:       const y = floorY + 4 + rnd() * (h - floorY - 8);
1366:       const rw = 3 + rnd() * 12;
1367:       ctx.fillStyle = `rgba(0,0,0,${0.3 + rnd() * 0.4})`;
1368:       ctx.beginPath();
1369:       ctx.ellipse(x, y, rw, rw * 0.28, 0, 0, TAU);
1370:       ctx.fill();
1371:     }
1372:     ctx.restore();
1373: 
1374:     // dust rolling
1375:     for (let i = 0; i < 4; i++) {
1376:       const x = ((t * (8 + i * 3) + i * 130) % (w + 200)) - 100;
1377:       ctx.fillStyle = `rgba(180,160,120,${0.025 + i * 0.008})`;
1378:       ctx.beginPath();
1379:       ctx.ellipse(x, floorY + 6, 80 + i * 20, 5 + i * 2, 0, 0, TAU);
1380:       ctx.fill();
1381:     }
1382:   }
1383: 
1384:   drawArenaProps(ctx, t) {
1385:     const { w, h, floorY } = this;
1386:     // barbed wire post left
1387:     ctx.save();
1388:     ctx.strokeStyle = 'rgba(0,0,0,0.6)';
1389:     ctx.lineWidth = 4;
1390:     ctx.beginPath();
1391:     ctx.moveTo(w * 0.06, floorY + 20);
1392:     ctx.lineTo(w * 0.065, floorY - 28);
1393:     ctx.stroke();
1394:     ctx.lineWidth = 1;
1395:     ctx.strokeStyle = 'rgba(120,110,90,0.14)';
1396:     for (let i = 0; i < 3; i++) {
