          <button class="btn small" data-action="salvagerun">RUN · ${fmt(cost)} CAPS</button>
        </div>`,
      actions: [{ label: 'CLOSE', kind: '' }],
      wide: true,
    });
  }
```

But `openModal` doesn't support `wide`. Add support: `openModal({ ..., wide })` toggles class `wide` on modal-card. Also max-height/scroll CSS.

`lootCard(item, context)`:
```js
  lootCard(item) {
    const rarity = rarityOf(item);
    const slot = GEAR_SLOT_MAP? We don't import GEAR_SLOT_MAP; import it or find in GEAR_SLOTS.
    const equipped = this.s.loadout[item.slot] === item.id;
    return `<div class="loot-card rarity-${rarity.id}${equipped ? ' equipped' : ''}" style="--rarity:${rarity.color}">
      <div class="lc-top"><span class="lc-rarity">${rarity.name}</span><span class="lc-level">LV.${item.level}</span></div>
      <strong class="lc-name">${item.name}</strong>
      <span class="lc-slot">${slot.name}</span>
      <div class="lc-stats">${gearStatLines(item).map(line=>`<span>${line}</span>`).join('')}</div>
      <div class="lc-actions">
        <button class="mini-btn" data-action="${equipped ? 'unequip' : 'equiploot'}" data-id="${item.id}" data-slot="${item.slot}">${equipped ? 'REMOVE' : 'EQUIP'}</button>
        <button class="mini-btn danger" data-action="scraploot" data-id="${item.id}">SCRAP +${scrapValue(item)}</button>
      </div>
    </div>`;
  }
```
Need escape item names? Generated names safe. Fine.

`openLootResults(items, title)`:
```js
  openLootResults(items, title) {
    this.modalKind = 'loot';
    this.lastLoot = { items: items.map(i=>i.id), title };
    if (!items.length) { openModal with no items; }
    const body = `<p>...</p><div class="loot-grid">${items.map(...).join('')}</div>`;
    this.openModal({ eyebrow:'SALVAGE RUN', title: title || 'Recovered gear', body, actions:[{label:'CLOSE'}], wide:true });
  }
```

`refreshOpenGear()`:
```js
  refreshOpenGear() {
    if (this.modalKind === 'gear') this.openGear();
    else if (this.modalKind === 'loot') {
      const ids = this.lastLoot?.items || [];
      const items = ids.map(id => this.s.inventory.find(it => it.id === id)).filter(Boolean);
      this.openLootResults(items, this.lastLoot?.title);
    }
  }
```
But `openGear` sets modalKind 'gear' and `openLootResults` sets 'loot'. Fine.

`closeModal()` should set modalKind = null.

`openModal` wide support:
```js
const card = modal.querySelector('.modal-card');
card.classList.toggle('wide', !!wide);
```
Also reset scrollTop maybe.

Dispatch cases:
- 'gear': g.ui.openGear()? Actually UI method; in dispatch use `this.openGear()`.
- 'salvagerun': g.salvageRun()
- 'equiploot': g.equipLoot(id)
- 'unequip': g.unequipSlot(slot)
- 'scraploot': g.scrapLoot(id)

Need `target.dataset.slot` and id.

Also topbar gear button uses data-action gear.

Important: The global click listener intercepts `[data-action]`; inside modal works. The modal backdrop click handler in main closes only when e.target.id === 'modal'; clicking buttons triggers both? Event bubbles to modal; e.target is button, not modal, so fine.

Add `buildLoadout()` call in constructor after buildZones maybe. Add `renderLoadout()` in render.

Also need `refreshOpenGear` called after `equipTool`/`equipWeapon`? Not necessary, but if gear modal open and user changes base equipment via Forge (not possible while modal open). Fine.

