  content: ""; position: absolute; top: 0; left: 0; width: 60px; height: 2px; background: var(--rust);
}
.modal-card h3 {
  font-size: 24px;
  letter-spacing: .1em;
  font-weight: 900;
  color: #f2ecda;
  margin: 4px 0 12px;
}
#modalBody {
