.modal-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; margin-top: 18px; }
.modal-actions .btn { padding: 9px 14px; }
@keyframes fadeIn { from { opacity: 0; } }

/* ── scrollbars ───────────────────────────────────────────── */
::-webkit-scrollbar { width: 7px; height: 7px; }
::-webkit-scrollbar-track { background: rgba(0,0,0,.18); }
::-webkit-scrollbar-thumb { background: #3c4234; border: 1px solid #191c15; }
::-webkit-scrollbar-thumb:hover { background: #5a5c45; }

/* ── responsive ───────────────────────────────────────────── */
@media (max-width: 1180px) and (min-width: 981px) {
  .layout { grid-template-columns: minmax(0, 1fr) minmax(0, .95fr) minmax(0, 1fr); gap: 8px; padding: 8px; }
  .panel-head { padding: 10px 11px 8px; }
  .panel-head h2 { font-size: 18px; }
  .mine-controls { grid-template-columns: 1fr; }
  .mine-meta { grid-template-columns: repeat(3, 1fr); padding: 5px 7px; }
  .mine-meta div:last-child { grid-column: auto; }
  .mine-meta div:last-child strong { font-size: 11px; }
  .res-chip { min-width: 64px; }
}

@media (max-width: 980px) {
  .topbar { min-height: 54px; padding: 6px 10px; gap: 10px; }
  .brand-mark { width: 28px; height: 28px; }
  .brand-mark svg { width: 24px; height: 24px; }

