    ctx.strokeStyle = `rgba(255,190,120,${0.5 * (1 - k)})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(8, -54, 44, -1.7, -1.7 + k * 2.1);
    ctx.stroke();
  }

  ctx.restore();
}

