function canAffordOre(state, oreCost) {
  return Object.entries(oreCost).every(([k, v]) => (state.ores[k] || 0) >= v);
}

/* Colour-codes the action box in the Forge: EQUIP / IN USE / UNLOCK / UPGRADE. */
function setCta(el, label, state) {
